  listen:[["I'll call you tonight.",["promise","prediction"],0],["I think it won't rain tomorrow.",["will rain","won't rain"],1],["I'll carry that for you.",["offer","prediction"],0],["Robots will teach in schools.",["prediction","promise"],0],["I won't eat pizza today.",["want","won't"],1,"Which word do you hear?"]],
  write:{task:"Write your predictions: 'My life and Valparaíso in 2040' (about 80 words).", model:"In 2040 I'll be 30 years old. I think I'll work as a marine engineer and I'll probably live near the sea. I won't have a car because I'll use electric buses. Valparaíso will be cleaner and there will be more tourists. I hope my family will be healthy and happy.",
    frame:["In 2040 I'll be ___.","I think I'll ___.","I probably won't ___.","Valparaíso will ___."], check:["Uso will y won't.","Uso I think / probably.","Verbo base después de will."]}
